/*
 * Starry Orbit — CasaMOD entry point (mod.js, generated by casamod/build.js).
 *
 * 1. Taps every same-origin <audio>/<video> that plays in this tab (the music
 *    player widget included) into a Web Audio analyser, so the wallpaper reacts
 *    to whatever is playing. The sound still reaches the speakers as usual.
 *    The tap is shared with the Live Wallpapers mod.
 * 2. Describes the CasaOS host to the engine: settings storage, language,
 *    which clicks count as the empty background, and when it is visible.
 * 3. Creates the wallpaper canvas right above CasaOS's own background image
 *    (which it hides while Starry Orbit is the chosen wallpaper) and below the
 *    rest of the UI.
 * 4. Loads the engine scripts from this mod's folder.
 * 5. Adds Starry Orbit to the CasaOS wallpaper menu, and a "Customize" button
 *    (the wallpaper settings) next to "Change" in the CasaOS settings dropdown.
 */
(function () {
  'use strict';

  if (window.__starryOrbitMod) return;
  window.__starryOrbitMod = true;

  var BASE = ((document.currentScript && document.currentScript.src) || '').replace(/[^/]*$/, '');
  var VERSION = '__VERSION__';
  var FILES = __FILES__;
  var TAG = '[Starry Orbit]';

  // ---------------------------------------------------------------------------
  // 1. Tab audio tap (casamod/src/shared/audio-tap.js, written in by build.js)
  // ---------------------------------------------------------------------------
  /*__AUDIO_TAP__*/
  audioTap.listen(function (analyser) {
    if (window.Starry && Starry.audio && Starry.audio.useAnalyser) Starry.audio.useAnalyser(analyser, 'tab');
  });

  // ---------------------------------------------------------------------------
  // 2. Host description for the engine
  // ---------------------------------------------------------------------------
  var wallpaperOn = false;

  // Presses on these never start a wave or a black hole
  var UI = 'a,button,input,textarea,select,label,img,video,audio,svg,[role="button"],[contenteditable],' +
    '[draggable="true"],.widget,.card,.dropdown,.modal,.navbar,.b-tooltip,.tooltip,.snackbar,.toast,' +
    '.context-menu,#so-settings,.smp-widget';

  window.Starry = window.Starry || {};
  Starry.host = {
    name: 'casaos',
    storageKey: 'casamod-starry-orbit',
    startupHint: false,
    menuHotkey: false,
    menuStyle: 'host',   // the panel wears the CasaOS look (casaos.css), not the wallpaper colors
    audioUI: 'tab',
    language: function () { return localStorage.getItem('lang') || ''; },
    active: function () { return wallpaperOn; },
    // The canvas sits behind CasaOS: a press counts when it lands on a large
    // empty container (the dashboard background), not on an icon or widget
    pointerTarget: function (e) {
      if (!wallpaperOn) return false;
      var t = e.target;
      if (!t || !t.closest || t.closest(UI)) return false;
      var r = t.getBoundingClientRect();
      return r.width * r.height >= window.innerWidth * window.innerHeight * 0.3;
    }
  };

  // ---------------------------------------------------------------------------
  // 3. Canvas layer, on when Starry Orbit is the chosen CasaOS wallpaper
  // ---------------------------------------------------------------------------
  // Picking "Starry Orbit" in the CasaOS wallpaper menu saves this mod's
  // wallpaper.jpg as the wallpaper: CasaOS keeps the choice on the server and
  // mirrors its path in localStorage.wallpaper (store mutation SET_WALLPAPER).
  var WALL_PATH = (function () {
    try { return new URL(BASE + 'wallpaper.jpg').pathname; } catch (e) { return '/mod/starry-orbit/wallpaper.jpg'; }
  })();
  var WALL_FROM = 'Starry Orbit';
  var selected = isOurs(localStorage.getItem('wallpaper'));
  var store = null;

  function isOurs(path) {
    return typeof path === 'string' && path.indexOf(WALL_PATH) >= 0;
  }

  var canvas = document.createElement('canvas');
  canvas.id = 'so-stars';
  canvas.setAttribute('aria-hidden', 'true');
  document.body.insertBefore(canvas, document.body.firstChild);

  // Shown where CasaOS shows its background (the dashboard), when chosen
  function syncBackground() {
    var on = selected && !!document.getElementById('background');
    if (on === wallpaperOn) return;
    wallpaperOn = on;
    document.documentElement.classList.toggle('so-wallpaper-on', on);
    var panel = document.getElementById('so-settings');
    if (!on && panel && !panel.hidden) Starry.menu.toggle();
  }

  // Follows later choices (this tab or, after a reload, any other device)
  function hookStore() {
    if (store) return;
    var app = document.getElementById('app');
    var vm = app && app.__vue__;
    if (!vm || !vm.$store || !vm.$store.state || !('wallpaperObject' in vm.$store.state)) return;
    store = vm.$store;
    store.watch(function (state) { return state.wallpaperObject; }, function (w) {
      selected = !!w && isOurs(w.path);
      syncBackground();
      injectRow();
    });
    // CasaOS may have loaded the saved choice (another device's) before the
    // hook: SET_WALLPAPER mirrors it in localStorage.wallpaper
    selected = isOurs(localStorage.getItem('wallpaper'));
    syncBackground();
    injectRow();
  }

  // ---------------------------------------------------------------------------
  // 5. CasaOS integration: a tile in the wallpaper menu, and "Customize" next
  //    to "Change" in the settings dropdown while Starry Orbit is the wallpaper
  // ---------------------------------------------------------------------------
  var ICON = '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" ' +
    'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
    '<path d="M12 3.5l1.7 4.3 4.3 1.7-4.3 1.7L12 15.5l-1.7-4.3L6 9.5l4.3-1.7z"/>' +
    '<path d="M18.5 14.5l.8 1.9 1.9.8-1.9.8-.8 1.9-.8-1.9-1.9-.8 1.9-.8z"/></svg>';
  var BTN_ID = 'so-customize';
  var ROW_ID = 'so-casaos-settings-row';
  var TILE_ID = 'so-wallpaper-tile';

  function setText(el, text) {
    if (el.textContent !== text) el.textContent = text;
  }

  function openSettings(e) {
    e.preventDefault();
    Starry.menu.open();
    // Buefy closes its dropdown on any click outside it
    setTimeout(function () { document.documentElement.click(); }, 0);
  }

  // Text button; just the sparkle (text as tooltip) when the row is too narrow
  // for the CasaOS label, "Customize" and "Change" in the current language
  function customizeButton() {
    var wrap = document.createElement('div');
    wrap.id = BTN_ID;
    wrap.className = 'ml-2';
    wrap.innerHTML = '<button type="button" class="button is-dark is-small is-rounded">' +
      '<span class="so-btn-text"></span><span class="so-btn-icon">' + ICON + '</span></button>';
    wrap.firstChild.addEventListener('click', openSettings);
    return wrap;
  }

  function fitButton(row) {
    var wrap = row.querySelector('#' + BTN_ID);
    if (!wrap || wrap.hidden || !row.clientWidth) return;   // closed dropdown: nothing to measure
    wrap.classList.remove('so-compact');
    if (row.scrollWidth > row.clientWidth + 1 || row.scrollHeight > row.clientHeight + 1) wrap.classList.add('so-compact');
  }

  // Measures when the row gets its size (the dropdown opens) or changes it
  var resizes = window.ResizeObserver && new ResizeObserver(function (entries) {
    entries.forEach(function (entry) { fitButton(entry.target); });
  });
  var watchedRow = null;

  // Layouts without a "Wallpaper" row: a row of its own after "Automount USB Drive"
  function fallbackRow() {
    var row = document.createElement('div');
    row.id = ROW_ID;
    row.className = 'is-flex is-align-items-center mb-1 _is-large _box hover-effect _is-radius pr-2 mr-4 ml-4';
    row.innerHTML =
      '<div class="is-flex is-align-items-center is-flex-grow-1 _is-normal">' +
      '<span class="icon mr-1 ml-2 is-20">' + ICON + '</span><span class="so-row-label"></span></div>';
    row.appendChild(customizeButton());
    return row;
  }

  // The settings row whose CasaOS icon has this class
  // (only among the settings rows: the dashboard's right-click menu is also a
  // .dropdown-content, with the same wallpaper icon on "Change wallpaper")
  function casaRow(icon) {
    var i = document.querySelector('.dropdown-content ._box .casa-' + icon);
    return i && i.closest('._box');
  }

  function injectRow() {
    if (!window.Starry || !Starry.menu) return;   // nothing to open yet
    var vanilla = casaRow('wallpaper-outline');
    var fallback = document.getElementById(ROW_ID);
    var wrap;
    if (vanilla) {
      if (fallback) fallback.remove();
      var change = vanilla.lastElementChild;   // the wrapper of CasaOS's "Change" button
      wrap = document.getElementById(BTN_ID) || customizeButton();
      // anywhere before "Change": the other mod's button may sit there too
      if (wrap.parentNode !== vanilla || !(wrap.compareDocumentPosition(change) & Node.DOCUMENT_POSITION_FOLLOWING)) {
        vanilla.insertBefore(wrap, change);
      }
    } else {
      var usb = casaRow('usb-outline');
      if (!usb) return;
      fallback = fallback || fallbackRow();
      if (usb.nextElementSibling !== fallback) usb.parentNode.insertBefore(fallback, usb.nextSibling);
      fallback.hidden = !selected;
      setText(fallback.querySelector('.so-row-label'), Starry.i18n.t('host.menuRow'));
      wrap = fallback.querySelector('#' + BTN_ID);
    }
    wrap.hidden = !selected;
    var text = Starry.i18n.t('host.menuButton');
    setText(wrap.querySelector('.so-btn-text'), text);
    if (wrap.firstChild.title !== text) wrap.firstChild.title = text;
    var row = wrap.closest('._box');
    if (resizes && row !== watchedRow) {
      if (watchedRow) resizes.unobserve(watchedRow);
      resizes.observe(row);
      watchedRow = row;
    }
    fitButton(row);
  }

  // The wallpaper menu (CasaOS-UI WallpaperModal.vue) lists two built-in images
  // and an upload button. The Starry Orbit tile is a copy of a built-in one (so
  // it keeps CasaOS's scoped styles); choosing it sets the modal's own state,
  // and CasaOS's "Apply" saves it like any other wallpaper.
  function injectTile() {
    var upload = document.getElementById('upload-wallpaper');
    var card = upload && upload.closest('.modal-card');
    var vm = card && card.__vue__;
    if (!vm || !('wallpaperItems' in vm) || card.querySelector('#' + TILE_ID)) return;
    var uploadCol = upload.closest('.column');
    var builtIn = uploadCol && uploadCol.parentNode.querySelector('.image-list-item');
    if (!builtIn) return;

    var tile = builtIn.closest('.column').cloneNode(true);
    tile.id = TILE_ID;
    var item = tile.querySelector('.image-list-item');
    item.classList.remove('active');
    item.title = 'Starry Orbit';
    var img = tile.querySelector('img');
    if (img) {
      img.removeAttribute('srcset');
      img.src = WALL_PATH;
      img.alt = 'Starry Orbit';
    }
    var badge = document.createElement('span');
    badge.className = 'so-tile-badge';
    badge.innerHTML = ICON;
    item.appendChild(badge);

    tile.addEventListener('click', function () {
      vm.path = WALL_PATH;
      vm.from = WALL_FROM;
      vm.backgroundStyleObj.backgroundImage = 'url(' + WALL_PATH + ')';
    });
    function mark() { item.classList.toggle('active', isOurs(vm.path)); }
    vm.$watch('path', mark);
    mark();
    uploadCol.parentNode.insertBefore(tile, uploadCol);
  }

  // One cheap, debounced observer for the background, the dropdown and the menu
  var scheduled = false;
  new MutationObserver(function () {
    if (scheduled) return;
    scheduled = true;
    setTimeout(function () {
      scheduled = false;
      hookStore();
      syncBackground();
      injectRow();
      injectTile();
    }, 120);
  }).observe(document.body, { childList: true, subtree: true });

  // ---------------------------------------------------------------------------
  // 4. Engine loader
  // ---------------------------------------------------------------------------
  // Downloaded in parallel, run in order (async = false)
  function load() {
    FILES.forEach(function (f, i) {
      var s = document.createElement('script');
      s.src = BASE + f + '?v=' + VERSION;
      s.async = false;
      if (i === FILES.length - 1) s.onload = started;
      s.onerror = function () { console.error(TAG, 'failed to load', f); };
      document.body.appendChild(s);
    });
  }

  function started() {
    if (audioTap.analyser) Starry.audio.useAnalyser(audioTap.analyser, 'tab');
    hookStore();
    syncBackground();
    injectRow();
    injectTile();
    console.info(TAG, 'loaded', VERSION);
  }

  syncBackground();
  load();
})();
